<section class="users-heading movement-heading"><div><h2>Mes mouvements</h2><p>Recettes et dépenses des véhicules auxquels vous êtes affecté.</p></div><label class="search-field"><i class="bi bi-search"></i><input id="movement-search" type="search" placeholder="Véhicule, référence, libellé…" oninput="filterMovements()"></label></section><section class="users-table-card"><div class="users-table-scroll"><table><thead><tr><th>Référence</th><th>Date</th><th>Véhicule</th><th>Type</th><th>Libellé</th><th>État</th><th>Montant</th></tr></thead><tbody id="movement-body"><?php foreach($mouvements as$m):$income=$m['type_operation']==='RECETTE';$search=strtolower($m['reference'].' '.$m['immatriculation'].' '.$m['libelle']);?><tr data-search="<?= htmlspecialchars($search) ?>"><td><strong><?= htmlspecialchars($m['reference']) ?></strong></td><td><?= date('d/m/Y',strtotime($m['date_operation'])) ?></td><td><?= htmlspecialchars($m['immatriculation']) ?></td><td><span class="movement-type <?= $income?'income':'expense' ?>"><i class="bi bi-arrow-<?= $income?'down-left':'up-right' ?>"></i><?= $income?'Recette':'Dépense' ?></span></td><td><?= htmlspecialchars($m['libelle']) ?></td><td><span class="movement-state <?= $m['cloturer']?'closed':'open' ?>"><?= $m['cloturer']?'Clôturé':'Ouvert' ?></span></td><td class="<?= $income?'positive':'negative' ?>"><strong><?= $income?'+':'-' ?><?= $fmt($m['montant'],$m['devise']) ?> <?= $m['devise'] ?></strong></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Espace employé</span></footer></main></div><script>function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}function filterMovements(){const q=document.getElementById('movement-search').value.toLowerCase().trim();document.querySelectorAll('#movement-body tr').forEach(r=>r.style.display=!q||r.dataset.search.includes(q)?'':'none')}</script></body></html>
